WITH unpivoted AS (SELECT * FROM (SELECT id, channel, shipping_fee, amount, discount FROM orders) src UNPIVOT INCLUDE NULLS (metric_value FOR kpi IN (shipping_fee, amount AS AMOUNT, discount AS DISCOUNT))) SELECT kpi, channel, COUNT_IF(channel = 'partner') AS partner_events, COUNT(DISTINCT kpi) AS distinct_kpis, MAX(metric_value) FILTER (WHERE kpi = 'DISCOUNT') AS discount_max_metric_value, ROUND(SUM(metric_value) / NULLIF(COUNT(CASE WHEN kpi = 'shipping_fee' THEN 1 END), 0), 2) AS metric_value_per_shipping_fee FROM unpivoted GROUP BY GROUPING SETS ((kpi, channel), (kpi), ()) ORDER BY channel
